add_action( 'woocommerce_before_add_to_cart_button', 'perfectpixel_addon_field' );
add_filter( 'woocommerce_add_to_cart_validation', 'perfectpixel_addon_validate', 10, 2 );
add_filter( 'woocommerce_add_cart_item_data', 'perfectpixel_addon_cart_data', 10, 2 );
add_filter( 'woocommerce_get_item_data', 'perfectpixel_addon_item_data', 10, 2 );
add_action( 'woocommerce_checkout_create_order_line_item', 'perfectpixel_addon_order_meta', 10, 3 );

function perfectpixel_addon_applies( $product_id ) {
	$ids = wp_parse_id_list( '{{addon_field_product_ids}}' );
	return ! $ids || in_array( (int) $product_id, $ids, true );
}

function perfectpixel_addon_value() {
	return isset( $_POST['perfectpixel_addon'] ) ? mb_substr( sanitize_text_field( wp_unslash( $_POST['perfectpixel_addon'] ) ), 0, 100 ) : '';
}

function perfectpixel_addon_field() {
	global $product;
	if ( ! $product || ! perfectpixel_addon_applies( $product->get_id() ) ) {
		return;
	}
	$required = 'yes' === '{{addon_field_required}}';
	printf(
		'<p class="form-row perfectpixel-addon" style="width:100%%"><label for="perfectpixel_addon">%s%s</label><input type="text" class="input-text" id="perfectpixel_addon" name="perfectpixel_addon" maxlength="100"%s></p>',
		esc_html( '{{addon_field_label}}' ),
		$required ? ' <abbr class="required">*</abbr>' : '',
		$required ? ' required' : ''
	);
}

function perfectpixel_addon_validate( $passed, $product_id ) {
	if ( perfectpixel_addon_applies( $product_id ) && 'yes' === '{{addon_field_required}}' && '' === perfectpixel_addon_value() && ! wp_doing_ajax() ) {
		wc_add_notice( '{{addon_field_error}}', 'error' );
		return false;
	}
	return $passed;
}

function perfectpixel_addon_cart_data( $data, $product_id ) {
	$value = perfectpixel_addon_value();
	if ( '' !== $value && perfectpixel_addon_applies( $product_id ) ) {
		$data['perfectpixel_addon'] = $value; // Different text = separate cart line.
	}
	return $data;
}

function perfectpixel_addon_item_data( $item_data, $cart_item ) {
	if ( ! empty( $cart_item['perfectpixel_addon'] ) ) {
		$item_data[] = array( 'key' => '{{addon_field_label}}', 'value' => $cart_item['perfectpixel_addon'] );
	}
	return $item_data;
}

function perfectpixel_addon_order_meta( $item, $cart_item_key, $values ) {
	if ( ! empty( $values['perfectpixel_addon'] ) ) {
		$item->add_meta_data( '{{addon_field_label}}', $values['perfectpixel_addon'], true );
	}
}
